input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zone ?zname WHERE {
  ?ahu a brick:AirHandler ; rdfs:label "AHU02".
  ?ahu brick:feedsAir ?zone.
  ?zone rdfs:label ?zname.
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?s ?p ?o WHERE {
  ?s brick:hasFeed ?o .
  FILTER regex(str(?s), "AHU02")
} LIMIT 50

SELECT DISTINCT ?p WHERE {
  ?s ?p ?o .
  FILTER (str(?s) like "%AHU02%" || str(?o) like "%AHU02%")
} LIMIT 50

SELECT DISTINCT ?p WHERE {
  ?s ?p ?o .
  ?s a brick:AirHandler.
} LIMIT 50

